/*
  DOIS JOGOS NUMA PLACA — menu pra escolher:
    1. ASSEMBLEIA — Campanha Civica em 3 Fases (Pelourinho / Salvador)
    2. DE SALVADOR A JUAZEIRO — pra Renata e Cintia
  Cintia Vitorino Independent Games

  ESP32 + TFT 1.8" ST7735 (128x160, SPI) + 2 botoes
  Bibliotecas: Adafruit GFX Library, Adafruit ST7735 and ST7789
  (Preferences.h ja vem no pacote oficial do ESP32)

  Arquivos desta pasta (os cinco precisam estar juntos):
    DoisJogos.ino    este arquivo
    principal.h      menu e ligacao entre os dois jogos
    assembleia.h     jogo da Assembleia
    jogo.h           jogo De Salvador a Juazeiro
    sprites.h        bonecas de lego, flores e baloes

  LIGACOES (as mesmas de antes)
    TFT  VCC -> 3V3     GND -> GND     LED/BL -> 3V3
         SCL/SCK -> GPIO18   SDA/MOSI -> GPIO23
         CS -> GPIO5   DC/A0 -> GPIO21   RES/RST -> GPIO22
    Botao A : GPIO32 <-> GND
    Botao B : GPIO33 <-> GND

  MENU: B troca de jogo, A entra.
  Dentro de qualquer jogo, segure A e B juntos por 3 segundos pra voltar ao menu.
*/

#include "principal.h"

uint32_t lastT = 0;

void setup() {
  pinMode(BTN_A, INPUT_PULLUP);
  pinMode(BTN_B, INPUT_PULLUP);
  tft.initR(INITR_BLACKTAB);
  tft.setRotation(1);            // 160x128 paisagem
  tft.fillScreen(0);
  principalInit();
}

void loop() {
  uint32_t now = millis();
  if (now - lastT < 33) return;  // ~30 quadros por segundo
  lastT = now;
  bool a = digitalRead(BTN_A) == LOW;
  bool b = digitalRead(BTN_B) == LOW;
  principalTick(a, b);
  tft.drawRGBBitmap(0, 0, tela.getBuffer(), 160, 128);
}
